create role anon;
create role authenticated;
create table public.workers (worker_id text primary key, worker_name text);
insert into public.workers values ('tester', 'Tester');
create function public.flexcon_require_active_worker(p_worker_id text) returns void language plpgsql as $$
begin
  if p_worker_id <> 'tester' then raise exception 'unauthorized'; end if;
end;
$$;
create table public.flexcon_authorizations (id uuid primary key default gen_random_uuid(), authorization_no text, full_name text, prefecture text);
create table public.flexcon_inspection_options (id uuid primary key default gen_random_uuid(), option_type text, name text, active boolean default true, sort_order integer default 0, created_at timestamptz default now());
create table public.flexcon_inspection_weights (weight_type text primary key, weight_kg integer);
create table public.flexcon_inspection_registrations (
  id uuid primary key default gen_random_uuid(), registration_no bigint generated by default as identity unique,
  authorization_id uuid references public.flexcon_authorizations, warehouse_id uuid references public.flexcon_inspection_options,
  settlement_no text, created_by_worker_id text, created_at timestamptz default now()
);
create table public.flexcon_inspection_flexcons (
  id uuid primary key default gen_random_uuid(), registration_id uuid references public.flexcon_inspection_registrations,
  authorization_id uuid references public.flexcon_authorizations, fiscal_year integer, purchase_date date,
  inspection_date date, inspector_name text, inspection_location text, record_kind text, flexcon_no integer,
  lot_number text unique, brand text, quantity_kg integer, grade text, reason text, moisture numeric,
  moisture_values numeric[] default '{}', created_by_worker_id text, updated_by_worker_id text,
  created_at timestamptz default now(), updated_at timestamptz default now(), unique(authorization_id, record_kind, flexcon_no)
);
create table public.flexcon_inspection_paper_bags (
  id uuid primary key default gen_random_uuid(), registration_id uuid references public.flexcon_inspection_registrations,
  authorization_id uuid references public.flexcon_authorizations, fiscal_year integer, purchase_date date,
  inspection_date date, inspector_name text, inspection_location text, brand text, bag_count integer,
  grade text, reason text, moisture numeric, moisture_values numeric[] default '{}',
  created_by_worker_id text, updated_by_worker_id text, created_at timestamptz default now(), updated_at timestamptz default now()
);
