create view public.flexcon_inventory_ledger_base as
select 'inspection-flexcon:' || d.id::text as id, null::bigint as registration_order,
  'inspection_flexcon'::text as source_type, 'inbound'::text as movement_type,
  d.purchase_date as movement_date, 'Tester'::text as worker_name, 'Producer'::text as producer_name,
  ''::text as settlement_no, '青森県'::text as origin, d.brand as product_name,
  coalesce(d.grade,'検査前') as grade, case when d.record_kind='bulk' then d.quantity_kg else 1 end::numeric as quantity,
  case when d.record_kind='bulk' then 'kg' else '本' end as unit, null::uuid as from_warehouse_id,
  r.warehouse_id as to_warehouse_id, '検査記録'::text as movement_from, w.name as movement_to, d.created_at, null::numeric as purchase_price
from public.flexcon_inspection_flexcons d join public.flexcon_inspection_registrations r on r.id=d.registration_id
join public.flexcon_inspection_options w on w.id=r.warehouse_id
union all
select 'inspection-paper:' || d.id::text, null::bigint, 'inspection_paper_bag','inbound',d.purchase_date,
  'Tester','Producer','','青森県',d.brand,coalesce(d.grade,'検査前'),d.bag_count::numeric,'袋',null::uuid,
  r.warehouse_id,'検査記録',w.name,d.created_at,null::numeric
from public.flexcon_inspection_paper_bags d join public.flexcon_inspection_registrations r on r.id=d.registration_id
join public.flexcon_inspection_options w on w.id=r.warehouse_id;
create view public.flexcon_inventory_ledger as select base.*,null::integer as crop_year from public.flexcon_inventory_ledger_base base;
create view public.flexcon_inventory_balances_base as
select base.to_warehouse_id as warehouse_id,base.movement_to as warehouse_name,base.origin,base.product_name,base.grade,base.unit,
sum(base.quantity)::numeric(14,3) as quantity from public.flexcon_inventory_ledger_base base
group by base.to_warehouse_id,base.movement_to,base.origin,base.product_name,base.grade,base.unit;
create view public.flexcon_inventory_balances as select * from public.flexcon_inventory_balances_base;
create view public.flexcon_inventory_balances_by_crop_year as select base.*,8 as crop_year from public.flexcon_inventory_balances_base base;
